import{_ as t}from"./chunks/flakiness-tab.DPwG2u1N.js";import{_ as s,o as a,c as i,a6 as n}from"./chunks/framework.CCKCzdWs.js";const g=JSON.parse('{"title":"Fails on CI, passes locally","titleTemplate":"Playwright test: :title | Piwi","description":"A Playwright test fails on CI and passes on your machine: see what differs between the two, check that it is the cause, reproduce it locally, then pin it in the config.","frontmatter":{"title":"Fails on CI, passes locally","titleTemplate":"Playwright test: :title | Piwi","description":"A Playwright test fails on CI and passes on your machine: see what differs between the two, check that it is the cause, reproduce it locally, then pin it in the config.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/recipes/fails-on-ci.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/recipes/fails-on-ci.html"}],["meta",{"property":"og:title","content":"Playwright test: Fails on CI, passes locally | Piwi"}],["meta",{"property":"og:description","content":"A Playwright test fails on CI and passes on your machine: see what differs between the two, check that it is the cause, reproduce it locally, then pin it in the config."}]]},"headers":[],"relativePath":"recipes/fails-on-ci.md","filePath":"recipes/fails-on-ci.md","lastUpdated":1795554528000}'),r={name:"recipes/fails-on-ci.md"};function o(h,e,l,p,d,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="why-does-my-playwright-test-fail-on-ci-but-pass-on-my-machine" tabindex="-1">Why does my Playwright test fail on CI but pass on my machine? <a class="header-anchor" href="#why-does-my-playwright-test-fail-on-ci-but-pass-on-my-machine" aria-label="Permalink to &quot;Why does my Playwright test fail on CI but pass on my machine?&quot;">​</a></h1><p>Something differs between the two machines, and when the test reads a date, a price or a sorted list, it is often the time zone or the language. A CI runner usually runs in <code>UTC</code> with <code>en-US</code>, your laptop in its own, and a browser takes both from its machine unless the Playwright config sets them.</p><p>Piwi records where each run executed, so you can read what differs and prove it before changing anything.</p><h2 id="_1-see-what-differs" tabindex="-1">1. See what differs <a class="header-anchor" href="#_1-see-what-differs" aria-label="Permalink to &quot;1. See what differs&quot;">​</a></h2><p>The run page&#39;s <strong>Environment</strong> line names the runner&#39;s time zone, locale, OS and Node.js version. Click it for every snapshot, shard by shard: the runner, each browser, each server under test (<a href="/features/run-environment.html">what each records</a>).</p><p>Then put the failure next to a pass:</p><ul><li><strong>Your machine&#39;s run.</strong> Report a run of the test from your machine to the same project, select it and the CI run on the project&#39;s <strong>Runs</strong> tab, and <strong>Compare</strong>: the <strong>Changes</strong> tab&#39;s <strong>Environment changes</strong> section lists the fields that differ (<a href="/features/run-changes.html#picking-another-baseline">comparing two runs</a>).</li><li><strong>The test&#39;s last pass.</strong> The failing execution&#39;s <strong>State</strong> tab diffs its environment against the test&#39;s last passing execution (<a href="/features/run-changes.html#one-execution-s-baseline">which one</a>).</li></ul><p>The runner&#39;s fields need only the reporter. A browser&#39;s own time zone and locale need the <a href="/guide/capture-fixtures.html">capture fixtures</a>: without them, the diff infers them from the config, else the runner, and labels them so. A server under test answers only through an <a href="/guide/backend-logs.html#server-environment">instrumentation package</a>. Nothing recorded, from an older reporter or with collection off? Print the time zone and locale in a CI step and in your terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;console.log(Intl.DateTimeFormat().resolvedOptions())&quot;</span></span></code></pre></div><h2 id="_2-check-whether-it-is-the-cause" tabindex="-1">2. Check whether it is the cause <a class="header-anchor" href="#_2-check-whether-it-is-the-cause" aria-label="Permalink to &quot;2. Check whether it is the cause&quot;">​</a></h2><p>A test that has ever passed on a retry has a <strong>Flakiness</strong> tab. Its suspects include the runner&#39;s time zone or locale when the test&#39;s failures share one value and its passes another, which takes both sides in its default-branch history: CI&#39;s failures, and passes reported from somewhere else, such as your machine (<a href="/features/flaky-tests.html#suspects">how suspects are found</a>).</p><figure><img src="'+t+`" alt="A flaky test&#39;s Flakiness tab: two suspects with their counts among failures and passes, the lab condition and result of each, the context a lab cannot apply, and the experiment that reproduced the flake"><figcaption>A test&#39;s suspects, each with the condition the Flake Lab applies to test it.</figcaption></figure><p>A suspect is a correlation. The <a href="/features/flake-lab.html">Flake Lab</a> turns it into a verdict: it runs the test with the browser in the suspect&#39;s time zone or locale, next to a control run, and says whether the failure reproduces. <strong>Copy command</strong> on the tab gives the command, with the test&#39;s id:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1842</span></span></code></pre></div><p>It needs the capture fixtures, which apply the condition inside the page, and the reporter&#39;s <code>PIWI_DASHBOARD_URL</code> and <code>PIWI_API_KEY</code>; the <a href="/features/flake-lab.html#in-the-desktop-app">desktop app</a> runs it for you. The lab sets the browser only, so a date your test code computes in Node.js does not follow it. Without the fixtures, for a test that fails on every CI attempt and so has no Flakiness tab, or for a date computed outside the browser, the <a href="#_3-reproduce-it-on-your-machine">next step</a> is the same check by hand.</p><h2 id="_3-reproduce-it-on-your-machine" tabindex="-1">3. Reproduce it on your machine <a class="header-anchor" href="#_3-reproduce-it-on-your-machine" aria-label="Permalink to &quot;3. Reproduce it on your machine&quot;">​</a></h2><p>Run the test with CI&#39;s time zone and <code>LANG</code>, as its runner snapshot shows them.</p><p>From Piwi, make them the project&#39;s <a href="/features/run-variables.html">run variables</a>: a project admin adds a <code>TZ</code> row and a <code>LANG</code> row in <strong>Project → Settings → Run variables</strong>. Every run Piwi starts for the project then gets them: <a href="/features/run-on-my-machine.html">Run on my machine</a> from the desktop app or <a href="/features/piwi-runner.html">Piwi Runner</a>, and the editors&#39; runs. Every command Piwi gives to copy, such as a run&#39;s retry command, starts with them. Run on my machine is experimental and off until an administrator turns it on; a copied command needs no app. Run variables apply to everyone on the project, so remove the rows when you are done, unless CI&#39;s values should be everyone&#39;s.</p><p>Not a project admin, or not running it through Piwi: set them in the terminal.</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-jLxl9" id="tab-LFoYSvj" checked><label data-title="Linux / macOS" for="tab-LFoYSvj">Linux / macOS</label><input type="radio" name="group-jLxl9" id="tab-ejvYIxK"><label data-title="Windows (PowerShell)" for="tab-ejvYIxK">Windows (PowerShell)</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TZ</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">UTC</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LANG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">en_US.UTF-8</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TZ</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;UTC&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LANG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;en_US.UTF-8&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; npx playwright test</span></span></code></pre></div></div></div><p>An <code>LC_ALL</code> set on your machine wins over <code>LANG</code>. On Windows, <code>LANG</code> changes the locale of neither Node.js nor the browser, and a browser may not follow <code>TZ</code>: the PowerShell command reproduces neither reliably. Pin <code>use.timezoneId</code> and <code>use.locale</code> in the config instead, the next step.</p><h2 id="_4-fix-it-for-good" tabindex="-1">4. Fix it for good <a class="header-anchor" href="#_4-fix-it-for-good" aria-label="Permalink to &quot;4. Fix it for good&quot;">​</a></h2><p>Pin the browser&#39;s time zone and locale in the Playwright config, so the browser runs the same on every machine, Windows included:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// playwright.config.ts</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> default</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> wrapConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  defineConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    use: { timezoneId: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;UTC&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, locale: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;en-US&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>They reach the browser only. A date your test code computes still follows the machine&#39;s <code>TZ</code>, and so does a server the config starts: give that date an explicit <code>timeZone</code>, and set <code>TZ</code> in <code>webServer.env</code>.</p><p>If the failure is a bug your users in other time zones would meet, pinning hides it: test that zone on purpose, with a Playwright project of its own. If the lab reproduced the failure, <a href="/features/flake-lab.html#verify-a-fix"><code>piwi flake verify</code></a> proves the fix under the same condition.</p><h2 id="_5-when-it-is-not-the-environment" tabindex="-1">5. When it is not the environment <a class="header-anchor" href="#_5-when-it-is-not-the-environment" aria-label="Permalink to &quot;5. When it is not the environment&quot;">​</a></h2><p>If nothing differs, or running with CI&#39;s values still passes on your machine, the cause is elsewhere:</p><ul><li><strong>A server under test restarted during the run, or its clock is off the runner&#39;s.</strong> The run&#39;s <strong>Environment</strong> line warns, and so does the State tab&#39;s diff (<a href="/features/run-environment.html#where-it-shows">the rule</a>). A clock offset breaks token expiry and &quot;created just now&quot; checks. Both need the instrumentation package; without it, read the server&#39;s own logs.</li><li><strong>The app under test was down.</strong> Everything fails at once, fast, on a navigation or connection error. Piwi flags such a run as an <a href="/features/environment-incidents.html">environment incident</a>, and <a href="./mass-failure.html">Forty tests are red</a> is the recipe.</li><li><strong>CI is slower or busier.</strong> A slow route, the load of the shard and a test running alongside can be suspects on the same Flakiness tab, and <a href="./regression-or-flaky.html">Regression or flake?</a> tells a new failure from an old flake.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/run-environment.html">Run environment</a>: what each snapshot records, and where it shows</li><li><a href="/features/flake-lab.html">Flake Lab</a>: confirm a suspect by experiment, then verify the fix</li><li><a href="/features/run-variables.html">Run variables</a>: what they apply to, and the names they refuse</li><li><a href="./regression-or-flaky.html">Regression or flake?</a>: when the question is your change, not the machine</li></ul>`,31)])])}const k=s(r,[["render",o]]);export{g as __pageData,k as default};
